/// Global blockstate id of `minecraft:air`.
pub fn air() -> u32 {
    0
}

const AIR: u32 = 0;
const CAVE_AIR: u32 = 12818;
const VOID_AIR: u32 = 12817;

/// True for air / cave_air / void_air — the blocks that do not count
/// toward a section's block count (doc §7.3).
pub fn is_air_like(id: u32) -> bool {
    id == AIR || id == CAVE_AIR || id == VOID_AIR
}

/// Look up a vanilla blockstate id from a block name and its properties
/// (any order). Returns `None` for non-vanilla (modded) or unknown blocks
/// or unknown property names/values.
pub fn lookup(name: &str, props: &[(String, String)]) -> Option<u32> {
    // Accept both `minecraft:stone` and bare `stone`; reject other namespaces.
    let short: &str = match name.find(':') {
        None => name,
        Some(i) if &name[..i] == "minecraft" => &name[i + 1..],
        Some(_) => return None,
    };
    let def = match BLOCKS.binary_search_by(|b| b.name.cmp(short)) {
        Ok(i) => &BLOCKS[i],
        Err(_) => return None,
    };
    if props.len() != def.props.len() {
        return None;
    }
    // Odometer: LAST property varies fastest.
    let mut idx: u32 = 0;
    let mut mult: u32 = 1;
    for (pname, values) in def.props.iter().rev() {
        let v = props.iter().find(|(k, _)| k == pname).map(|(_, v)| v.as_str())?;
        let vi = values.iter().position(|x| *x == v)? as u32;
        idx += vi * mult;
        mult *= values.len() as u32;
    }
    Some(def.min_id + idx)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn p(pairs: &[(&str, &str)]) -> Vec<(String, String)> {
        pairs.iter().map(|(k, v)| (k.to_string(), v.to_string())).collect()
    }

    #[test]
    fn air_and_stone() {
        assert_eq!(lookup("minecraft:air", &[]), Some(0));
        assert_eq!(lookup("stone", &[]), Some(1));
    }

    #[test]
    fn multi_property_odometer() {
        // oak_log: min 130, axis x=0 y=1 z=2
        assert_eq!(lookup("minecraft:oak_log", &p(&[("axis", "x")])), Some(130));
        assert_eq!(lookup("oak_log", &p(&[("axis", "y")])), Some(131));
        assert_eq!(lookup("minecraft:oak_log", &p(&[("axis", "z")])), Some(132));
    }

    #[test]
    fn unknown_is_none() {
        assert_eq!(lookup("gtceu:machine", &[]), None);
        assert_eq!(lookup("minecraft:stone", &p(&[("bogus", "x")])), None);
    }
}
